export default {
  version: 1,
  name: "Settled Prop Shadow Bridge",
  description: "After a prop stays still for 30 ticks, its lantern-cast shadow becomes solid. The shadow lasts one tick and refreshes only while the prop remains still, so movement dissolves the bridge on the next simulation tick.",
  rules: [
    {
      id: "settled-prop-shadow",
      each: "prop",
      when: {
        all: [
          { compare: { left: { field: "stationaryTicks" }, op: "gte", right: 30 } },
          { compare: { left: { field: "speed" }, op: "eq", right: 0 } }
        ]
      },
      actions: [
        { type: "projectShadow", maxLength: 480, thickness: 12, lifetime: 1, solid: true }
      ]
    }
  ]
} satisfies RuleModule;
